#!/usr/bin/env node
'use strict';

/*
 * Audits charges generated by the 2026-08-15 RecurringDaily feature.
 * It NEVER changes data unless all of --apply --void-unbilled and
 * --created-since=<ISO date/time> are supplied.
 */
require('dotenv').config();

const mongoose = require('mongoose');
const IPDCharge = require('../models/IPDCharge');

const args = process.argv.slice(2);
const apply = args.includes('--apply');
const voidUnbilled = args.includes('--void-unbilled');
const hospitalArg = args.find((v) => v.startsWith('--hospital-id='));
const sinceArg = args.find((v) => v.startsWith('--created-since='));
const hospitalId = hospitalArg?.split('=')[1];
const createdSinceText = sinceArg?.slice('--created-since='.length);

if (!process.env.MONGO_URI || !mongoose.isValidObjectId(hospitalId) || !createdSinceText) {
  console.error('MONGO_URI, --hospital-id=<ObjectId>, and --created-since=<ISO date/time> are required');
  process.exit(2);
}
const createdSince = new Date(createdSinceText);
if (Number.isNaN(createdSince.getTime())) {
  console.error('--created-since must be a valid ISO date/time');
  process.exit(2);
}
if (apply && !voidUnbilled) {
  console.error('--apply is accepted only together with --void-unbilled');
  process.exit(2);
}

(async () => {
  await mongoose.connect(process.env.MONGO_URI);
  const filter = {
    hospitalId: new mongoose.Types.ObjectId(hospitalId),
    sourceModule: 'RecurringDaily',
    isAutoGenerated: true,
    createdAt: { $gte: createdSince }
  };

  const rows = await IPDCharge.find(filter)
    .select('_id admissionId chargeType description chargeDateKey rate netAmount status isBilled billId invoiceId createdAt')
    .sort({ admissionId: 1, chargeDateKey: 1, chargeType: 1 })
    .lean();

  const byType = {};
  let total = 0;
  let safelyVoidable = 0;
  let financiallyLocked = 0;
  for (const row of rows) {
    const type = row.chargeType || 'Unknown';
    byType[type] = byType[type] || { count: 0, amount: 0 };
    byType[type].count += 1;
    byType[type].amount += Number(row.netAmount || 0);
    total += Number(row.netAmount || 0);
    const locked = row.status === 'INVOICED' || row.isBilled || row.billId || row.invoiceId;
    if (locked) financiallyLocked += 1;
    else if (row.status === 'ACTIVE') safelyVoidable += 1;
  }

  for (const value of Object.values(byType)) {
    value.amount = Number(value.amount.toFixed(2));
  }

  const report = {
    mode: apply ? 'apply-void-unbilled' : 'audit-only',
    hospitalId,
    createdSince: createdSince.toISOString(),
    generatedCharges: rows.length,
    totalAmount: Number(total.toFixed(2)),
    safelyVoidable,
    financiallyLocked,
    byType,
    voided: 0
  };

  if (apply && voidUnbilled) {
    const result = await IPDCharge.updateMany(
      {
        ...filter,
        status: 'ACTIVE',
        isBilled: { $ne: true },
        billId: null,
        invoiceId: null
      },
      {
        $set: {
          status: 'VOIDED',
          voidedAt: new Date(),
          voidReason: 'Administrative rollback of unintended historical RecurringDaily startup catch-up'
        }
      }
    );
    report.voided = result.modifiedCount || 0;
  }

  console.log(JSON.stringify(report, null, 2));
  await mongoose.disconnect();
})().catch(async (error) => {
  console.error(error);
  try { await mongoose.disconnect(); } catch {}
  process.exit(1);
});
